#include <vector>
#include <climits>

using namespace std;

class Solution {
public:
    int minFallingPathSum(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<int> prev = grid[0];

        for (int i = 1; i < m; ++i) {
            int min1 = INT_MAX, min2 = INT_MAX, idx1 = -1;
            for (int j = 0; j < n; ++j) {
                if (prev[j] < min1) {
                    min2 = min1;
                    min1 = prev[j];
                    idx1 = j;
                } else if (prev[j] < min2) {
                    min2 = prev[j];
                }
            }
            vector<int> curr(n);
            for (int j = 0; j < n; ++j) {
                curr[j] = grid[i][j] + (j == idx1 ? min2 : min1);
            }
            prev = curr;
        }

        return *min_element(prev.begin(), prev.end());
    }
};
